package com.axsos.Life.models; import jakarta.persistence.*; import java.time.LocalDate; import static com.axsos.Life.models.Enums.*;
@Entity @Table(name="inbody_reports") public class InBodyReport extends BaseEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; private LocalDate reportDate;
 private Double weight; private Double muscleMass; private Double bodyFatPercentage; private Integer visceralFatLevel; private Double totalBodyWater; private Integer bmr; private Double bmi;
 @Column(length=4000) private String analysisSummary; @Column(length=2000) private String comparisonSummary; @Enumerated(EnumType.STRING) private InBodySource source;
 public Long getId(){return id;} public void setId(Long v){id=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public LocalDate getReportDate(){return reportDate;} public void setReportDate(LocalDate v){reportDate=v;} public Double getWeight(){return weight;} public void setWeight(Double v){weight=v;} public Double getMuscleMass(){return muscleMass;} public void setMuscleMass(Double v){muscleMass=v;} public Double getBodyFatPercentage(){return bodyFatPercentage;} public void setBodyFatPercentage(Double v){bodyFatPercentage=v;} public Integer getVisceralFatLevel(){return visceralFatLevel;} public void setVisceralFatLevel(Integer v){visceralFatLevel=v;} public Double getTotalBodyWater(){return totalBodyWater;} public void setTotalBodyWater(Double v){totalBodyWater=v;} public Integer getBmr(){return bmr;} public void setBmr(Integer v){bmr=v;} public Double getBmi(){return bmi;} public void setBmi(Double v){bmi=v;} public String getAnalysisSummary(){return analysisSummary;} public void setAnalysisSummary(String v){analysisSummary=v;} public String getComparisonSummary(){return comparisonSummary;} public void setComparisonSummary(String v){comparisonSummary=v;} public InBodySource getSource(){return source;} public void setSource(InBodySource v){source=v;}
}
